fn encode_batch_orders(v: &Value, buf: &mut [u8]) -> Result<usize, String> {
    let mut enc = batch_orders_codec::BatchOrdersEncoder::default().wrap(WriteBuf::new(buf), message_header_codec::ENCODED_LENGTH);
    enc = enc.header(0).parent().map_err(sbe_err)?;
    let cv = &v["record"];
    let mut c = enc.record_encoder();
    c.sequence(ju(cv, "sequence") as u64);
    c.sequenced_at(ju(cv, "sequencedAt") as u64);
    c.sequencer_group(ju(cv, "sequencerGroup") as u16);
    enc = c.parent().map_err(sbe_err)?;
    enc.session_id(ju(v, "sessionId") as u64);
    enc.account_id(ju(v, "accountId") as u64);
    let items = ja(v, "entries");
    let mut g = enc.entries_encoder(items.len() as u16, batch_orders_codec::encoder::EntriesEncoder::default());
    for item in items {
        g.advance().map_err(sbe_err)?;
        g.entry_type(enum_batch_entry_type(item, "entryType")?);
        g.client_order_id_zero_padded(js(item, "clientOrderId").as_bytes());
        g.instrument_id(ju(item, "instrumentId") as u64);
        g.order_id_opt(item.get("orderId").and_then(|x| x.as_u64()).map(|x| x as u64));
        g.side(enum_side(item, "side")?);
        g.entered_contract(enum_contract(item, "enteredContract")?);
        g.tick(ju(item, "tick") as u16);
        g.quantity(ju(item, "quantity") as u32);
        g.time_in_force(enum_time_in_force(item, "timeInForce")?);
        g.expires_at_opt(item.get("expiresAt").and_then(|x| x.as_u64()).map(|x| x as u64));
        g.at_event_start(enum_at_event_start(item, "atEventStart")?);
        g.flags(set_order_flags(item, "flags")?);
        g.protection_ticks(ju(item, "protectionTicks") as u8);
        g.spend_cap_cents_opt(item.get("spendCapCents").and_then(|x| x.as_i64()).map(|x| x as i64));
        g.entered_stake_cents_opt(item.get("enteredStakeCents").and_then(|x| x.as_i64()).map(|x| x as i64));
        g.client_order_group_opt(item.get("clientOrderGroup").and_then(|x| x.as_u64()).map(|x| x as u32));
    }
    enc = g.parent().map_err(sbe_err)?;
    Ok(enc.get_limit())
}

fn decode_batch_orders<'a>(header: MessageHeaderDecoder<ReadBuf<'a>>, buf: &'a [u8]) -> Result<Value, String> {
    let mut m = Map::new();
    m.insert("msg".into(), json!("BatchOrders"));
    let mut dec = batch_orders_codec::BatchOrdersDecoder::default().header(header, 0);
    let mut c = dec.record_decoder();
    let mut cm = Map::new();
    cm.insert("sequence".into(), json!(c.sequence()));
    cm.insert("sequencedAt".into(), json!(c.sequenced_at()));
    cm.insert("sequencerGroup".into(), json!(c.sequencer_group()));
    dec = c.parent().map_err(sbe_err)?;
    m.insert("record".into(), Value::Object(cm));
    m.insert("sessionId".into(), json!(dec.session_id()));
    m.insert("accountId".into(), json!(dec.account_id()));
    let mut g = dec.entries_decoder();
    let mut arr = Vec::new();
    while g.advance().map_err(sbe_err)?.is_some() {
        let mut im = Map::new();
    im.insert("entryType".into(), json!(    g.entry_type().to_string()));
    im.insert("clientOrderId".into(), json!(bytes_str(&    g.client_order_id())));
    im.insert("instrumentId".into(), json!(    g.instrument_id()));
    im.insert("orderId".into(),     g.order_id().map_or(Value::Null, |x| json!(x)));
    im.insert("side".into(), json!(    g.side().to_string()));
    im.insert("enteredContract".into(), json!(    g.entered_contract().to_string()));
    im.insert("tick".into(), json!(    g.tick()));
    im.insert("quantity".into(), json!(    g.quantity()));
    im.insert("timeInForce".into(), json!(    g.time_in_force().to_string()));
    im.insert("expiresAt".into(),     g.expires_at().map_or(Value::Null, |x| json!(x)));
    im.insert("atEventStart".into(), json!(    g.at_event_start().to_string()));
    im.insert("flags".into(), set_json_order_flags(    g.flags()));
    im.insert("protectionTicks".into(), json!(    g.protection_ticks()));
    im.insert("spendCapCents".into(),     g.spend_cap_cents().map_or(Value::Null, |x| json!(x)));
    im.insert("enteredStakeCents".into(),     g.entered_stake_cents().map_or(Value::Null, |x| json!(x)));
    im.insert("clientOrderGroup".into(),     g.client_order_group().map_or(Value::Null, |x| json!(x)));
        arr.push(Value::Object(im));
    }
    dec = g.parent().map_err(sbe_err)?;
    m.insert("entries".into(), Value::Array(arr));
    let _ = &mut dec;
    Ok(Value::Object(m))
}

